import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CWvfYWS8.js";import"./chunks/assets.Bz7j3IzC.js";var i=JSON.parse(`{"title":"Creating and organizing cgroups","description":"","frontmatter":{},"headers":[],"relativePath":"ch002.md","filePath":"ch002.md"}`),a={name:`ch002.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="creating-and-organizing-cgroups" tabindex="-1">Creating and organizing cgroups <a class="header-anchor" href="#creating-and-organizing-cgroups" aria-label="Permalink to “Creating and organizing cgroups”">​</a></h1><p>Initially, only the root cgroup exists, to which all processes belong. You create an empty child cgroup by adding a subdirectory:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/cg1</span></span></code></pre></div><p>Each cgroup has an interface file called cgroup.procs that lists the PIDs of all processes belonging to the cgroup, one per line. A process can be moved to a cgroup by writing its PID into the cgroup&#39;s cgroup.procs file:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24982</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/cg1/cgroup.procs</span></span></code></pre></div><p>Only one process can be migrated on a single write call. If a process is composed of multiple threads, writing the PID of any thread migrates all threads of the process.</p><div class="warning custom-block"><p>Note: A process can be in only one cgroup at a time.</p></div><h2 id="designing-a-cgroup-hierarchy" tabindex="-1">Designing a cgroup hierarchy <a class="header-anchor" href="#designing-a-cgroup-hierarchy" aria-label="Permalink to “Designing a cgroup hierarchy”">​</a></h2><p>Controllers can be enabled in any cgroup from the root to the leaves. Each controller distributes its system resource along the hierarchy, according to its configuration and the configuration of the hierarchy’s subtrees.</p><p>You specify controllers for each cgroup using two interface files that appear in every cgroup—including the root and all its children:</p><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">cgroup.controllers</td><td style="text-align:left;">Lists the controllers <strong>available</strong> in a cgroup. In the root cgroup, it lists all the controllers available on the system. In child cgroups it lists the controllers specified in its parent&#39;s <code>cgroup.subtree_control</code> file (see below).</td></tr><tr><td style="text-align:left;">cgroup.subtree_control</td><td style="text-align:left;">Lists the controllers that are <strong>active</strong> (enabled) in the cgroup’s subtrees. The controllers listed here are the ones available to descendant cgroups; they&#39;re listed in the <code>cgroup.controllers</code> file in descendant cgroups.</td></tr></tbody></table><p>You activate or deactivate controllers by writing their names to <code>cgroup.subtree_control</code>, each preceded by either a plus sign (+) to enable it, or a minus sign (-) to disable it, as in this example:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;+cpu -memory&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/cg1/cgroup.subtree_control</span></span></code></pre></div><p>In the hierarchy below, each <code>cgroup.subtree_control</code> file determines the set of controllers available to its child cgroups, i.e., the controllers that appear in the <code>cgroup.controllers</code> file of its children.</p><p><img src="/p002/ch00/002.png" alt="" width="720" height="405"></p><p>In this example, the root cgroup distributes resources to two partitions: <code>system.slice</code> where system processes run, and <code>workload.slice</code>, where production workload apps typically run. The set of resource controllers available to child cgroups with services like <code>crond.service</code>, or <code>smc_proxy.service</code>, is further restricted by the <code>cgroup.subtree_control</code> files of their respective parents.</p><h2 id="the-fbtax2-cgroup-hierarchy" tabindex="-1">The fbtax2 cgroup hierarchy <a class="header-anchor" href="#the-fbtax2-cgroup-hierarchy" aria-label="Permalink to “The fbtax2 cgroup hierarchy”">​</a></h2><div class="danger custom-block"><p>The cgroup hierarchy used for the <strong>fbtax2</strong> project is similar to the one above, but introduces some additional structures and best practices.</p><p>It divides the hierarchy into three top-level cgroups, each with its own purpose. In addition to the <code>system.slice</code> cgroup where system binaries run, it also includes:</p><ul><li><code>hostcritical.slice</code></li><li><code>workload.slice</code></li></ul><p><img src="/p002/ch00/003.png" alt="" width="716" height="226"></p><h4 id="hostcritical-slice" tabindex="-1">hostcritical.slice <a class="header-anchor" href="#hostcritical-slice" aria-label="Permalink to “hostcritical.slice”">​</a></h4><p>This cgroup protects processes required to keep the host running. It contains critical host management functions like sshd, and <a href="./ch012.html#oomd-memory-pressure-based-oom">oomd</a>, an alternative to the system OOM (out-of-memory) killer, that we&#39;ll look at in a <a href="./ch012.html#oomd-in-the-fbtax2-project">later section</a> of this case study.</p><h4 id="workload-slice" tabindex="-1">workload.slice <a class="header-anchor" href="#workload-slice" aria-label="Permalink to “workload.slice”">​</a></h4><p>Protecting the main workload from resource conflicts with system binaries was a primary goal of the project, and that&#39;s the main purpose of <code>workload.slice</code>. In this case, the main workload gets its own child cgroup <code>workload-container.slice</code> to protect hhvm.</p><p>Another child cgroup, <code>workload-support.slice</code>, provides protection to some of the system binaries needed to keep the main workload running. For example, if binaries like <code>workload-support.service</code> fail, the main workload can also fail. The exact set of system binaries a workload needs, and the amount of resources allocated to them, will differ depending on the context. But protecting required binaries in a cgroup like <code>workload-support.slice</code> helps ensure they&#39;re available to keep the main workload running.</p><p>In the <a href="./ch003.html#memory-pressure-in-the-fbtax2-project">next section</a> of this case study, we&#39;ll look at how <strong>fbtax2</strong> uses PSI memory pressure metrics.</p></div><h2 id="additional-notes-about-cgroup-hierarchies" tabindex="-1">Additional notes about cgroup hierarchies <a class="header-anchor" href="#additional-notes-about-cgroup-hierarchies" aria-label="Permalink to “Additional notes about cgroup hierarchies”">​</a></h2><p>All controller behaviors are hierarchical: if you enable a controller on a cgroup, it affects all processes belonging to the cgroups in its sub-hierarchy.</p><p>Similarly, most of the statistics you can query in cgroups, such as current memory or CPU usage, show the sum for the entire subtree.</p><p>Restrictions set closer to the root in the hierarchy can&#39;t be overridden from further away. When you enable a controller on a nested cgroup, it always restricts the resource distribution further.</p><div class="warning custom-block"><p>Note: The sum of the resources consumed by child cgroups can&#39;t exceed the total amount of resources available to the parent.</p></div><h3 id="avoiding-resource-conflicts-between-parent-and-child-cgroups" tabindex="-1">Avoiding resource conflicts between parent and child cgroups <a class="header-anchor" href="#avoiding-resource-conflicts-between-parent-and-child-cgroups" aria-label="Permalink to “Avoiding resource conflicts between parent and child cgroups”">​</a></h3><p>To eliminate situations where child cgroups compete for resources against the internal processes of their parent, cgroups can control distribution of memory and IO to their children only when they contain no processes of their own. In other words, cgroups can either contain tasks or control resources for child cgroups, but not both.</p><div class="warning custom-block"><p class="custom-block-title"></p><p>Note: An exception to this rule is the root cgroup, which can both contain processes and control resource distribution.</p></div><p>Thus, if a parent cgroup controls resource distribution to its child(ren) (i.e., by having a non-empty <code>cgroup.subtree_control</code> file) any processes in the parent cgroup must be moved to their own child cgroups.</p><p>For instance, a cgroup like <code>/cg1/cg2</code> can contain processes, but if <code>/cg1</code> also contains any processes of its own, those processes should be moved to their own leaf node, e.g., <code>/cg1/cg3</code>.</p><p>For certain legacy configurations, the CPU controller can also contain processes and control resource distribution. See the sections on thread mode on the <a href="http://man7.org/linux/man-pages/man7/cgroups.7.html" target="_blank" rel="noreferrer">cgroup manpage</a> for details.</p><h2 id="other-useful-cgroup-interface-files" tabindex="-1">Other useful cgroup interface files <a class="header-anchor" href="#other-useful-cgroup-interface-files" aria-label="Permalink to “Other useful cgroup interface files”">​</a></h2><p>These cgroup interface files come in handy when designing and testing a cgroup hierarchy:</p><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>cgroup.events</code></td><td style="text-align:left;">Contains key/value pairs that identify states or events for the cgroup. <br> <br> Events or state changes generate <code>file-modified</code> events that allow applications to track and monitor changes. <br> <br> The <code>populated</code> field indicates whether or not the cgroup or any of its descendants contain any active processes: 1 indicates the cgroup and/or its children contain active processes; 0 means there are no active processes.</td></tr><tr><td style="text-align:left;"><code>cgroup.max.depth</code></td><td style="text-align:left;">Specifies the limit on the nesting depth of descendant cgroups. 0 indicates no descendant cgroups can be created. Default is <code>max</code>.</td></tr><tr><td style="text-align:left;"><code>cgroup.max.descendants</code></td><td style="text-align:left;">Specifies the limit of the number of descendant cgroups that a cgroup may have. Writing the string <code>max</code> to this file means that no limit is imposed. Default value is <code>max</code>.</td></tr></tbody></table>`,32)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};